import{_ as d,o as t,c as o,a0 as c}from"./chunks/framework.C3yZ6M33.js";const h=JSON.parse('{"title":"Campaign schema","description":"","frontmatter":{},"headers":[],"relativePath":"reference/campaign-schema.md","filePath":"reference/campaign-schema.md"}'),r={name:"reference/campaign-schema.md"};function a(i,e,n,s,l,p){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="campaign-schema" tabindex="-1">Campaign schema <a class="header-anchor" href="#campaign-schema" aria-label="Permalink to &quot;Campaign schema&quot;">​</a></h1><p>The full YAML → <code>Campaign</code> contract, ported from v1 <code>model.ts</code>. The typed model lives in <code>peregrin-core</code> (<code>Campaign::from_dict</code>, <code>Node::from_dict</code>); expansion passes (<code>include</code>, <code>snippet</code>, discovery) run first in <code>peregrin-loader-yaml</code>. <code>from_dict</code> is total for nodes — bad scalars coerce or drop — but <code>nodes:</code>/<code>events:</code> that aren&#39;t arrays are a hard error.</p><h2 id="campaign-fields" tabindex="-1">Campaign fields <a class="header-anchor" href="#campaign-fields" aria-label="Permalink to &quot;Campaign fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>Campaign name.</td></tr><tr><td><code>nodes</code></td><td><code>[Node]</code></td><td>The graph — see node fields below.</td></tr><tr><td><code>events</code></td><td><code>[EventSchema]</code></td><td>Declared event contracts; under <code>strict</code> every entry must compile a payload schema.</td></tr><tr><td><code>functions</code></td><td>map or <code>[FunctionDefinition]</code></td><td>YAML-declared template functions. Map form injects the key as <code>name</code>. Fields: <code>driver</code>, <code>params</code>, <code>capabilities</code>, <code>requires_capability</code>, <code>deterministic</code>, <code>returns</code>.</td></tr><tr><td><code>config</code></td><td>map</td><td>Campaign config — <code>${config.*}</code> in templates; also <code>fan_in.count_from</code> source.</td></tr><tr><td><code>include</code></td><td><code>[path]</code></td><td>File composition (alias <code>includes</code>).</td></tr><tr><td><code>import</code></td><td><code>[path | {file, as}]</code></td><td>Python modules for python-driver handlers.</td></tr><tr><td><code>stop_on</code></td><td><code>[type]</code></td><td>Exact-match run terminators.</td></tr><tr><td><code>payload_schemas</code></td><td><code>{type: schema}</code></td><td>Per-event-type JSON schemas; <code>*.event.json</code> discoveries fold in here.</td></tr><tr><td><code>capabilities</code></td><td>map</td><td>Workflow capability policy (secrets, agents, urls, shell/http/python/webhook allow-deny, <code>default_policy</code>).</td></tr><tr><td><code>strict</code></td><td>bool</td><td>Strict validation mode (ADR-0001); JS-truthy parse.</td></tr><tr><td><code>state</code></td><td>map</td><td>Campaign-level state seed for <code>${state.*}</code>.</td></tr><tr><td><code>annotations</code></td><td>map</td><td>Free-form metadata (ADR-0009).</td></tr><tr><td><code>snippets</code></td><td><code>{name: body}</code></td><td><strong>Load-time only</strong> — consumed by the expansion pass; never reaches the typed model.</td></tr><tr><td><code>supersede</code></td><td>map</td><td>Queue policy for trigger events that outpace the executor — <code>key</code> (template over the trigger payload, e.g. <code>&quot;{repo}:{ref}&quot;</code>), <code>mode</code> (<code>latest-wins</code> | <code>fifo</code>), <code>cancel_running</code> (bool). Declared <strong>plus</strong> an ingress-driver node engages supervisor mode — see <a href="./queue-supersede.html">Queue &amp; supersede</a>.</td></tr><tr><td><code>runs_on</code></td><td><code>[label]</code></td><td>Runner labels this campaign requires (PL-007 fleet scheduling). Every label must appear in the hosting node&#39;s advertised capabilities (<code>/api/node</code>, fed by <code>PEREGRIN_RUNNER_LABELS</code>) — AND semantics; empty matches anywhere. Enforced by <code>campaign.start</code> ops, <code>campaign serve</code> hosting, and hub fleet dispatch — see <a href="./fleet-runners.html">Fleet runners</a>.</td></tr></tbody></table><h2 id="node-fields" tabindex="-1">Node fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Unique within the campaign.</td></tr><tr><td><code>driver</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Registry name (<code>shell</code>, <code>agent</code>, <code>runner</code>, <code>noop</code>, …). Empty driver = pure event node.</td></tr><tr><td><code>handler</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Handler reference within the driver.</td></tr><tr><td><code>on</code></td><td><code>[pattern]</code></td><td><code>[]</code></td><td>Glob subscription — see <a href="./on-grammar.html"><code>on:</code> grammar</a>.</td></tr><tr><td><code>emits</code></td><td><code>[type]</code></td><td><code>[]</code></td><td>Declared output types — strict-checked <strong>exact</strong>.</td></tr><tr><td><code>mode</code></td><td><code>any</code> | <code>all</code></td><td><code>any</code></td><td>Trigger semantics.</td></tr><tr><td><code>params</code></td><td>map</td><td><code>{}</code></td><td>Driver params — template-resolved at fire time.</td></tr><tr><td><code>max_fires</code></td><td>int | <code>&quot;unlimited&quot;</code></td><td><code>1</code></td><td>Fire cap. <code>0</code>/negative/non-integer falls back to the default (v1 quirk, kept — strict rejection is an ADR-0082 <em>fix</em> item). <code>driver: schedule</code> defaults to <code>unlimited</code>.</td></tr><tr><td><code>until</code></td><td><code>[type]</code></td><td><code>[]</code></td><td>Exact-match stop-listening list.</td></tr><tr><td><code>retire_on</code></td><td><code>[type]</code></td><td><code>[]</code></td><td>Exact-match retire list — removes the node from the live graph.</td></tr><tr><td><code>retry</code></td><td>map</td><td><code>{}</code></td><td><code>max_attempts</code> (default 1), <code>delay</code> secs (default 1), <code>backoff</code>: <code>fixed</code> | <code>linear</code> | <code>exponential</code>. Exhausted → <code>node.failed</code> + DLQ enqueue.</td></tr><tr><td><code>circuit_breaker</code></td><td>map</td><td>none</td><td>Present → breaker armed. <code>threshold</code> (default 5), <code>reset_after</code> secs (default 60), <code>on_trip</code> event type (default <code>circuit.open</code>). Success resets.</td></tr><tr><td><code>poll</code></td><td>map | truthy</td><td>none</td><td>Presence flips to poll mode — see normalization below.</td></tr><tr><td><code>fan_in</code></td><td>map</td><td>none</td><td>Count join over <code>on[0]</code>: <code>count</code>, <code>count_from</code> (config path), <code>emit</code> override.</td></tr><tr><td><code>forward</code></td><td><code>[pattern]</code></td><td><code>[]</code></td><td>Re-emit each trigger with capture substitution — see <a href="./event-envelope.html">Event envelope</a>.</td></tr><tr><td><code>resources</code></td><td>map</td><td><code>{}</code></td><td><code>weight</code> (min 1) against the run&#39;s concurrency gate (cap 50 — inert under the sequential runner, kept for parity).</td></tr><tr><td><code>capabilities</code></td><td>map</td><td><code>{}</code></td><td>Node capability policy — merged over the workflow&#39;s (see below). <code>merge: true</code> unions list keys.</td></tr><tr><td><code>state</code></td><td>map</td><td><code>{}</code></td><td><code>key</code> — template resolving to a scoped-store key; <code>skip_if</code> — template, truthy (<code>true</code>/<code>yes</code>/<code>1</code>/<code>ok</code>, trimmed, case-insensitive) skips the fire with <code>node.skipped</code>.</td></tr><tr><td><code>annotations</code></td><td>map</td><td><code>{}</code></td><td>Free-form metadata.</td></tr><tr><td><code>input</code></td><td>EventSchema (no <code>type</code>)</td><td>none</td><td>Params contract — overrides <code>driver.input</code>.</td></tr><tr><td><code>output</code></td><td><code>{type: EventSchema}</code></td><td><code>{}</code></td><td>Per-emitted-type payload contracts; node entries override driver <code>output</code>.</td></tr></tbody></table><h2 id="eventschema" tabindex="-1"><code>EventSchema</code> <a class="header-anchor" href="#eventschema" aria-label="Permalink to &quot;`EventSchema`&quot;">​</a></h2><p><code>{type, fields, schema, annotations}</code> — used by <code>events:</code>, node <code>input:</code>/<code>output:</code>, and driver contracts.</p><ul><li><code>fields</code> shorthand: <code>name: &lt;json-type&gt;[?]</code> where <code>?</code> marks optional; unknown type names compile to <code>string</code>.</li><li><code>schema</code> is a full JSON-schema dict and <strong>wins over <code>fields</code></strong> when non-empty.</li><li>Compiled schema checks <code>required</code> properties and per-property primitive <code>type</code> (<code>string</code>/<code>integer</code>/<code>number</code>/<code>boolean</code>/<code>array</code>/ <code>object</code>/<code>null</code>); non-object payloads fail <code>(root)</code>.</li></ul><h2 id="load-time-normalization" tabindex="-1">Load-time normalization <a class="header-anchor" href="#load-time-normalization" aria-label="Permalink to &quot;Load-time normalization&quot;">​</a></h2><p>Applied by <code>Node::from_dict</code> / the loader expansion, in order:</p><ol><li><strong>Discovery</strong> — <code>.peregrin/</code> then <code>.handl/</code> then the base dir (recursive, dot-dirs skipped; the named roots win name dedupes in scan order — <code>.peregrin</code> is the rebrand name, <code>.handl</code> stays for v1 compatibility): <code>*.node.yml</code>, <code>*.snippet.yml</code>, <code>*.event.json</code>, <code>*.config.yml</code>, <code>*.fn.yml</code> fold into <code>nodes</code>, <code>snippets</code>, <code>payload_schemas</code>, <code>config</code>, <code>functions</code>. <code>*.handler.py</code>, <code>*.secret.yml</code>, <code>.env</code> are discovered for other consumers.</li><li><strong><code>include:</code></strong> — a dict-level key deep-merges file contents <em>under</em> local keys; the top-level <code>include:</code> list does the same per path. <code>${include(path)}</code> inside strings splices the parsed value (typed when it&#39;s the whole string). Circular includes error by path.</li><li><strong><code>snippets:</code></strong> — <code>snippet: &lt;parent&gt;</code> inheritance inside the table resolves to a fixpoint (local wins); <code>snippet: &lt;name&gt;</code> in any dict merges the body under local keys; <code>${snippet(name)}</code> interpolates like <code>${include()}</code>. Cycles and non-dict bodies error.</li><li><strong>Deep merge</strong> — dicts merge per-key local-wins, arrays concatenate local-first, scalars take local.</li><li><strong><code>with:</code> rejection</strong> — any node <code>with:</code> key is a hard load error (renamed <code>params</code>, ADR-0025).</li><li><strong>Poll normalization</strong> — a truthy <code>poll:</code> appends <code>&lt;id&gt;.tick</code> to <code>on</code> and <code>emits</code>, merges <code>poll.until</code> into <code>until</code>, and backfills <code>params.interval</code> from <code>poll.interval</code>.</li><li><strong>Schedule normalization</strong> — <code>driver: schedule</code> appends <code>&lt;id&gt;.fire</code> to <code>on</code> and <code>&lt;id&gt;.fire</code> + <code>&lt;id&gt;.scheduled</code> to <code>emits</code> (the <code>poll:</code> <code>&lt;id&gt;.tick</code> convention, ADR-0018) and defaults <code>max_fires: unlimited</code>. Each landed <code>&lt;id&gt;.fire</code> re-invokes the driver to arm the next cron occurrence.</li><li><strong>Self-trigger default</strong> — <code>driver: cli</code>/<code>polling</code> with <code>params.mode != &quot;interval&quot;</code> defaults <code>max_fires: 100</code> (others: 1; <code>schedule</code>: <code>unlimited</code>).</li></ol><p>Coercion quirks kept from v1: scalar strings in list positions iterate into characters (<code>on: start</code> → <code>[&quot;s&quot;,&quot;t&quot;,&quot;a&quot;,&quot;r&quot;,&quot;t&quot;]</code>) — always write lists; <code>strict</code>, <code>requires_capability</code>, <code>deterministic</code> parse JS-truthy.</p><h2 id="capability-merge" tabindex="-1">Capability merge <a class="header-anchor" href="#capability-merge" aria-label="Permalink to &quot;Capability merge&quot;">​</a></h2><p><code>capabilities</code> merges <code>{...workflow, ...node}</code> for the template ctx and via <code>CapabilityChecker.merge</code> for driver-param checks: node keys override; dict-list keys (<code>shell</code>, <code>http</code>, <code>python</code>, <code>webhook</code>) merge their <code>allow</code>/<code>deny</code>/<code>ports</code>/<code>hosts</code>/<code>paths</code> lists; top-level list keys (<code>secrets</code>, <code>agents</code>, <code>urls</code>) replace — or union when the node sets <code>merge: true</code>. <code>default_policy</code> defaults to <code>deny</code> under <code>strict</code>, <code>allow</code> otherwise.</p>',15)])])}const u=d(r,[["render",a]]);export{h as __pageData,u as default};
